package com.tnc.tnc.life.routes;
import java.util.*;
public final class RouteBooks {
    public static List<String> pages(String id){var pages=new ArrayList<String>();switch(id){
        case "season_handbook"->{pages.add("四时农圃\n\n每季七日，一年二十八日。应季正常长，相邻季六成，反季四分之一。换季不会杀死作物。睡觉推进农历，成长只累计真实运行时间。\n\n厨房配方请用 JEI 查看当前配方。");pages.add("春：绿叶、根菜、嫩莓。\n夏：水稻、瓜果、热带果。\n秋：谷物、葡萄、果园。\n冬：根菜、卷心菜、冰葡萄。\n\n菌菇、水生与异境植物保持原种法。护候灯在封闭温室中恢复应季速度。");}
        case "magic_garden_book"->{pages.add("魔植花园\n\n野外成熟果实可直接种；纤维作物挖根得种与产物；多年生株拿普通剪刀取芽。无需采样夹。\n\n土源：八泥土＋一满魔力瓶。十秒转同层九乘九泥土。流动魔力灌溉八格。缺灌溉只暂停，不死亡。");for(var s:com.tnc.tnc.life.botanical.BotanicalSpecies.values())pages.add(s.name+"\n\n"+s.help+"\n\n产物："+s.productName+"。人工栽培需魔法土和流动魔力。种子可保留，也可交易。");for(var s:NewPlantKind.values())pages.add(s.name+"\n\n"+s.help+"。\n\n产物："+s.productName+"。成长不挑群系，特殊条件只控制供魔。");}
        case "beast_ranch_book"->{pages.add("异兽牧场\n\n先喂喜食取得短暂信任，再持笼长按捕获。灵纹、曜纹、星髓三级分别需要三、五、八秒。\n\n牧务杖选兽，右键栖居标记设窝。地面九乘九，飞行九乘九乘九。再喂食照料建立归属，食槽提供实际饲料。");for(var s:com.tnc.tnc.life.pasture.PastureSpecies.ALL)pages.add(s.name()+"\n\n喜食："+new net.minecraft.world.item.ItemStack(s.food()).getHoverName().getString()+"\n产物："+s.product()+"\n笼级："+com.tnc.tnc.life.pasture.PastureCageItem.tierFor(s.id())+"\n\n取产与工作共享资源和食物，停工不会饿死。具体状态空手右键查看。");}
        default->{pages.add("魔导工坊 · 从第一炉开始\n\n先备24炉砖、炉口、炉核、排烟顶。底层9砖；中层7砖、核居中、炉口朝前；顶层8砖、烟居中。\n\n右键炉口开GUI。手动注魔每次25M，铁锭＋60M先做灵纹铁。此时不用抓兽种花。");pages.add("阶段二 · 田边的第一束魔力\n\n注能台：潜行右键开面板，放瓶或桶；空手按住右键，每秒注入自身5M。瓶100、桶400。\n\n8泥土围满瓶制土源，放地面等10秒。田边倒魔力桶，8格内土壤泛青蓝微光。");pages.add("阶段三 · 花园给机器供能\n\n先种翠脉枝。成株每2秒蓄1M，缓冲40M。根旁放集露盏，再逐格接青辉导魔晶纤→浅魔池→锯台。\n\n锯台放1原木，12M、4秒得6木板。检流尺看哪一段缺魔力。线路也可接炉口。");pages.add("阶段四 · 选择自己的工坊\n\n需要纸、布、旅粮：压机、织机、烘食器。\n需要农牧便利：收获臂、自动投料器、温室灯。\n需要扩建：高阶晶纤、储池、折光镜。\n\n动物先安置喂食，再以牧务杖绑定集息器。鲸是储池，不会自己产魔力。\n\n折光镜：拿检流尺，潜行右键先选一面、再选另一面。普通12格、远折24格，取两端较小距离；支持斜向与高低差，需要无遮挡。镜面自动转向。空手潜行右键解除配对。");pages.add("输能与充能\n\n晶纤带宽8/32/128M每秒，储池1000/8000/32000M。共享同根线合计限流，每段最多双端，可转弯和竖接；分支用独立分流装置。只在加载区工作。\n\n饰品充能台：第一输入格放充能饰品或机甲，线路供魔，普通饰品16M/秒，天穹式机铠128M/秒（受供能和带宽限制）。机铠占胸甲位、容量12000M。\n\n六联晶铳：穿铠后按住右键，12M一发，不用箭；潜行右键换元素。V突进，B屏障，G过载，潜行V震荡。屏障挡伤还要耗魔，长射会过热。完整步骤见魔导工坊页。");}
    }if(id.equals("mana_workshop_book")){pages.add(0,"魔导纪行 · 当前主线\n\nT1提纯/控温/寻迹；T2伴生/点化/五行药膳；T3天体转相/同源温养/天路；T4跨维绿洲/终局武装。\n\n自动农业只作可选工坊。FTB《魔导纪行·T0—T4》按次序引导。");pages.add("剥离与控温\n\n剥离台200M/8M每秒；左一原料，15M/3秒提纯。根芯供续魔药，药粉供共鸣酊与温养祭坛，草木丝可织雾布。\n引火桩贴药锅：左拍火+60，右拍水-60；每次5M。\n寻迹仪400M：耗200M，F8指引真实未探索地点30秒。");pages.add("生态与药雾\n\n共鸣台400M/16：贴集息器或色靶，亲喂后真实产魔才凝宝，一次照料一份。\n熏蒸釜1000M/32：一药、40M、10秒，点化3×3。扭曲水植80%变蒸莲；巨人催巨果；分裂洗礼幼兽；坚肤药预处理左二金锭或钻石，使锻炉耗魔减半。");pages.add("同源温养\n\n转相仪4000M/256：左一放不消耗的元素信物，太阳/太阴1:1转七系。\n王杖放温养祭坛，匹配元素最高256M/秒，满10000M后持下界之星、龙息或Boss突破核右键觉醒。拒绝异系，不喂魔药。");pages.add("跨维与终局\n\n主世界塔旁4格内放棱镜，检流尺潜行选中，再点下界/末地棱镜。塔每秒100M维护，最多4096M跨维输送，撑48格绿洲。\n无魔区无自然回蓝或魔植产能，随身药与余额仍可使用。\n下界绿洲炼机铠/晶铳，末地绿洲或露天极光炼零式/羽翼。");}return catalogue(id,pages);}
    private static List<String> catalogue(String id,List<String> fallback){try(var stream=RouteBooks.class.getResourceAsStream("/data/tnc/life_routes/catalogue.json")){var root=com.google.gson.JsonParser.parseReader(new java.io.InputStreamReader(java.util.Objects.requireNonNull(stream),java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();var out=new ArrayList<String>();if(id.equals("mana_workshop_book"))out.addAll(fallback);else{out.add(fallback.get(0));if(fallback.size()>1)out.add(fallback.get(1));}String category=switch(id){case "season_handbook"->"traditional";case "magic_garden_book"->"magic";case "beast_ranch_book"->"animals";default->"machines";};for(var raw:root.getAsJsonArray(category)){var e=raw.getAsJsonObject();String name=e.get("name").getAsString();String text=name+"\n\n";if(category.equals("traditional")){text+="适种："+e.get("seasons").getAsString()+"\n种源："+e.get("item").getAsString()+"\n\n"+e.get("use").getAsString()+"\n原模组配方例："+(e.has("recipes")?e.get("recipes").toString():"无")+"。以JEI当前启用配方为准。";}else if(category.equals("magic")){text+=e.get("help").getAsString()+"\n\n种源："+e.get("seed").getAsString()+"\n产物："+e.get("product").getAsString()+"\n用途："+e.get("use").getAsString();}else if(category.equals("animals")){text+="喜食："+e.get("food").getAsString()+"\n产物："+e.get("product").getAsString()+"\n栖居："+e.get("habitat").getAsString()+"\n笼级："+com.tnc.tnc.life.pasture.PastureCageItem.tierFor(e.get("id").getAsString());}else{text+=e.get("help").getAsString();}while(text.length()>225){out.add(text.substring(0,225));text=text.substring(225);}out.add(text);}return out;}catch(java.io.IOException|RuntimeException e){return fallback;}}
}
